begin;
create temp table checks(label text);
create function pg_temp.check(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;insert into checks values(label);end$$;
create temp table fixture(property_id uuid,actor_id uuid,upload_id uuid,second_id uuid,recovery_id uuid,asset_id uuid,input jsonb,second_input jsonb,payload jsonb);
insert into fixture select gen_random_uuid(),id,gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),null,jsonb_build_object('contentHash',repeat('a',64),'size',100,'mimeType','image/png','extension','png','metadata','{"name":"Fixture asset","description":"Original description","asset_type":"image","rights_status":"unknown","rights_metadata":{"license":"Private license note"},"tags":[]}'::jsonb),null,null from public.profiles where org_id='22222222-2222-2222-2222-222222222222' and role='admin' limit 1;
insert into public.properties(id,org_id,name)select property_id,'22222222-2222-2222-2222-222222222222','ForgeStudio asset rollback fixture' from fixture;
do $$declare f fixture;r jsonb;begin
 select * into f from fixture;
 perform pg_temp.check(public.begin_forgestudio_asset_upload(f.upload_id,f.property_id,gen_random_uuid(),f.input)->>'state'='forbidden','upload starts only under current property access');
 r:=public.begin_forgestudio_asset_upload(f.upload_id,f.property_id,f.actor_id,f.input);
 perform pg_temp.check(r->>'state'='prepared' and r->>'storagePath'=f.property_id||'/forgestudio/uploads/'||f.upload_id||'.png','request records an exact immutable storage destination');
 perform pg_temp.check(public.begin_forgestudio_asset_upload(f.upload_id,f.property_id,f.actor_id,f.input)->>'state'='prepared','interrupted upload can resume the same identity');
 perform pg_temp.check(public.begin_forgestudio_asset_upload(f.upload_id,f.property_id,f.actor_id,f.input||jsonb_build_object('contentHash',repeat('b',64)))->>'state'='request_conflict','another file cannot reuse the upload request');
 perform pg_temp.check((select count(*)=1 from public.shared_action_events where property_id=f.property_id and action='studio.asset.upload.requested'),'upload intent is recorded once');
 perform pg_temp.check(not has_table_privilege('authenticated','public.forgestudio_asset_uploads','select') and not has_function_privilege('authenticated','public.manage_forgestudio_asset(uuid,uuid,uuid,jsonb)','execute'),'browser cannot bypass private upload and edit decisions');
 update fixture set payload=jsonb_build_object('contentHash',repeat('a',64),'storagePath',r->>'storagePath','storageBucket','property-assets','storageVerified',true,'fileUrl','https://example.invalid/original.png');
 begin perform public.finish_forgestudio_asset_upload(f.upload_id,f.property_id,f.actor_id,'{}');raise exception 'FAIL unproven storage';exception when raise_exception then if SQLERRM<>'Stored file evidence required' then raise;end if;end;
 perform pg_temp.check(not exists(select 1 from public.content_assets where property_id=f.property_id),'unconfirmed storage cannot create a library record');
end$$;
create function pg_temp.fail_asset_history() returns trigger language plpgsql as $$begin if new.action='studio.asset.uploaded' then raise exception 'Fixture asset history failure';end if;return new;end$$;
create trigger asset_fixture_failure before insert on public.shared_action_events for each row execute function pg_temp.fail_asset_history();
do $$declare f fixture;begin select * into f from fixture;
 begin perform public.finish_forgestudio_asset_upload(f.upload_id,f.property_id,f.actor_id,f.payload);raise exception 'FAIL partial asset';exception when raise_exception then if SQLERRM<>'Fixture asset history failure' then raise;end if;end;
 perform pg_temp.check(not exists(select 1 from public.content_assets where property_id=f.property_id) and (select state='prepared' from public.forgestudio_asset_uploads where id=f.upload_id),'history failure preserves the recoverable upload without a partial asset');
end$$;
drop trigger asset_fixture_failure on public.shared_action_events;
do $$declare f fixture;r jsonb;a public.content_assets;command uuid:=gen_random_uuid();input jsonb;begin
 select * into f from fixture;
 r:=public.recover_forgestudio_asset_upload(f.recovery_id,f.property_id,f.actor_id,jsonb_build_object('uploadId',f.upload_id,'action','recover','reason','Verified the stored file after an interrupted save','storage',f.payload));
 perform pg_temp.check(r->>'state'='saved' and r->>'assetId'=f.upload_id::text,'stored file recovery completes the original request');
 perform pg_temp.check(public.recover_forgestudio_asset_upload(f.recovery_id,f.property_id,f.actor_id,jsonb_build_object('uploadId',f.upload_id,'action','recover','reason','Verified the stored file after an interrupted save','storage',f.payload))->>'state'='replayed','lost recovery reply returns the exact saved decision');
 perform pg_temp.check(public.begin_forgestudio_asset_upload(f.upload_id,f.property_id,f.actor_id,f.input)->>'state'='replayed','reselecting the same file after success cannot duplicate it');
 select * into a from public.content_assets where id=f.upload_id;update fixture set asset_id=a.id;
 perform pg_temp.check(a.approval_status='pending' and a.content_hash=repeat('a',64),'saved file has exact byte identity and awaits usage review');
 perform pg_temp.check(not exists(select 1 from public.shared_action_events where property_id=f.property_id and (request::text||coalesce(after_state::text,'')||result::text) like '%Private license note%'),'shared actions omit private license text and full asset snapshots');
 input:=jsonb_build_object('assetId',a.id,'revision',a.governance_revision,'action','save','patch','{"name":"Updated asset","folder":"Community","is_favorite":true,"tags":["pool"]}'::jsonb);
 r:=public.manage_forgestudio_asset(command,f.property_id,f.actor_id,input);
 perform pg_temp.check(r->>'state'='saved' and r->'asset'->>'folder'='Community' and (r->'asset'->>'is_favorite')::boolean,'folder and favorite changes persist in real columns');
 perform pg_temp.check(public.manage_forgestudio_asset(command,f.property_id,f.actor_id,input)->>'state'='replayed','lost metadata reply keeps a stable decision identity');
 perform pg_temp.check(public.manage_forgestudio_asset(gen_random_uuid(),f.property_id,f.actor_id,input)->>'state'='stale_asset','an old opened version cannot overwrite a newer edit');
 select * into a from public.content_assets where id=a.id;
 r:=public.manage_forgestudio_asset(gen_random_uuid(),f.property_id,f.actor_id,jsonb_build_object('assetId',a.id,'revision',a.governance_revision,'action','review','reason','Owner reviewed the current usage and recorded the restriction','review',jsonb_build_object('approval_status','approved','rights_status','restricted','expires_at',clock_timestamp()-interval '1 day')));
 perform pg_temp.check(r->>'state'='saved' and r->'asset'->>'approval_status'='approved','ForgeStudio records rights expiry as advisory under the existing owner policy');
 begin update public.content_assets set file_url='https://example.invalid/replaced-in-place.png' where id=a.id;raise exception 'FAIL mutable file';exception when raise_exception then if SQLERRM not like 'Archive this saved asset%' then raise;end if;end;
 perform pg_temp.check(true,'a saved uploaded file identity cannot be overwritten');
 begin delete from public.content_assets where id=a.id;raise exception 'FAIL deleted file';exception when raise_exception then if SQLERRM not like 'Archive this saved asset%' then raise;end if;end;
 perform pg_temp.check(true,'hard deletion cannot erase the saved file and history');
 select * into a from public.content_assets where id=a.id;
 r:=public.manage_forgestudio_asset(gen_random_uuid(),f.property_id,f.actor_id,jsonb_build_object('assetId',a.id,'revision',a.governance_revision,'action','archive','reason','Remove this photo from new use'));
 perform pg_temp.check(r->>'state'='saved' and r->'asset'->>'approval_status'='rejected' and r->'asset'->>'archived_at' is not null,'archive disables new use while preserving its record');
 begin update public.content_assets set approval_status='approved' where id=a.id;raise exception 'FAIL archive bypass';exception when check_violation then null;end;
 perform pg_temp.check(true,'another path cannot reapprove an archived asset');
 select * into a from public.content_assets where id=a.id;
 r:=public.manage_forgestudio_asset(gen_random_uuid(),f.property_id,f.actor_id,jsonb_build_object('assetId',a.id,'revision',a.governance_revision,'action','restore','reason','Restore for a fresh usage review'));
 perform pg_temp.check(r->>'state'='saved' and r->'asset'->>'approval_status'='pending' and r->'asset'->>'archived_at' is null,'restoration requires a fresh review and does not restore approval');
 perform pg_temp.check((select count(*)>=5 from public.brand_asset_revisions where asset_id=a.id),'immutable versions retain successive edits and decisions');
end$$;
do $$declare f fixture;r jsonb;a public.content_assets;replacement_input jsonb;path text;begin
 select * into f from fixture;select * into a from public.content_assets where id=f.asset_id;
 replacement_input:=f.input||jsonb_build_object('contentHash',repeat('b',64),'replacesAssetId',a.id,'expectedRevision',a.governance_revision,'reason','Replace with the newly reviewed photo');
 r:=public.begin_forgestudio_asset_upload(f.second_id,f.property_id,f.actor_id,replacement_input);path:=r->>'storagePath';
 update public.content_assets set name='Separate edit after upload began' where id=a.id;
 r:=public.finish_forgestudio_asset_upload(f.second_id,f.property_id,f.actor_id,jsonb_build_object('contentHash',repeat('b',64),'storagePath',path,'storageBucket','property-assets','storageVerified',true,'fileUrl','https://example.invalid/replacement.png'));
 perform pg_temp.check(r->>'state'='replacement_changed','replacement cannot archive an asset edited after upload began');
 perform pg_temp.check((select state='prepared' from public.forgestudio_asset_uploads where id=f.second_id),'replacement conflict retains the saved upload for recovery');
 r:=public.recover_forgestudio_asset_upload(gen_random_uuid(),f.property_id,f.actor_id,jsonb_build_object('uploadId',f.second_id,'action','keep_separate','reason','Keep the stored file without changing the edited original','storage',jsonb_build_object('contentHash',repeat('b',64),'storagePath',path,'storageBucket','property-assets','storageVerified',true,'fileUrl','https://example.invalid/replacement.png')));
 perform pg_temp.check(r->>'state'='saved' and (select archived_at is null from public.content_assets where id=a.id),'explicit recovery can keep the stored file separately');
 replacement_input:=f.input||jsonb_build_object('contentHash',repeat('c',64),'replacesAssetId',a.id,'expectedRevision',(select governance_revision from public.content_assets where id=a.id),'reason','Use the revised photo while retaining the original');
 update fixture set second_id=gen_random_uuid(),second_input=replacement_input;
end$$;
do $$declare f fixture;r jsonb;a public.content_assets;begin
 select * into f from fixture;
 r:=public.begin_forgestudio_asset_upload(f.second_id,f.property_id,f.actor_id,f.second_input);
 r:=public.finish_forgestudio_asset_upload(f.second_id,f.property_id,f.actor_id,jsonb_build_object('contentHash',repeat('c',64),'storagePath',r->>'storagePath','storageBucket','property-assets','storageVerified',true,'fileUrl','https://example.invalid/second-replacement.png'));
 perform pg_temp.check(r->>'state'='saved' and r->>'replacedAssetId'=f.asset_id::text,'replacement creates a new file and records its original identity');
 perform pg_temp.check((select archived_at is not null and replacement_asset_id=f.second_id and file_url='https://example.invalid/original.png' from public.content_assets where id=f.asset_id),'replacement archives the original without rewriting its file');
 perform pg_temp.check(exists(select 1 from public.shared_action_events where property_id=f.property_id and action='studio.asset.replaced'),'replacement decision commits with its resulting library state');
 perform pg_temp.check((select approval_status='pending' from public.content_assets where id=f.second_id),'replacement approval is independent of the original');
end$$;
select count(*) as passed_assertions from checks;
rollback;
